source = '''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    outside = {(r, c) for r in range(h) for c in range(w) if (r in (0, h - 1) or c in (0, w - 1)) and grid[r][c] == 0}
    queue = deque(outside)
    while queue:
        r, c = queue.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in outside:
                outside.add((nr, nc))
                queue.append((nr, nc))
    remaining = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0 and (r, c) not in outside}
    result = [row[:] for row in grid]
    fill_by_width = {3: 8, 5: 4, 7: 3}
    while remaining:
        start = remaining.pop()
        component = {start}
        q = deque([start])
        while q:
            r, c = q.popleft()
            for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if (nr, nc) in remaining:
                    remaining.remove((nr, nc))
                    component.add((nr, nc))
                    q.append((nr, nc))
        width = max(c for r, c in component) - min(c for r, c in component) + 1
        color = fill_by_width[width]
        for r, c in component:
            result[r][c] = color
    return result
'''
